package com.arjunren.bus;
import java.nio.charset.StandardCharsets;import java.security.*;import java.sql.*;import java.time.*;import java.util.HexFormat;
public final class AuthService{private final Database db;private final PasswordService passwords;private final SecureRandom random=new SecureRandom();public AuthService(Database db,PasswordService passwords){this.db=db;this.passwords=passwords;}public Session login(String username,String password){try(var c=db.connection();var s=c.prepareStatement("SELECT id,password_hash,role FROM users WHERE username=?")){s.setString(1,username);try(var r=s.executeQuery()){if(!r.next()||!passwords.verify(password,r.getString(2)))throw new SecurityException("Invalid credentials");byte[] value=new byte[32];random.nextBytes(value);var token=HexFormat.of().formatHex(value);try(var insert=c.prepareStatement("INSERT INTO sessions(token_hash,user_id,expires_at) VALUES(?,?,?)")){insert.setString(1,digest(token));insert.setLong(2,r.getLong(1));insert.setObject(3,OffsetDateTime.now(ZoneOffset.UTC).plusHours(2));insert.executeUpdate();}return new Session(token,r.getLong(1),r.getString(3));}}catch(SQLException e){throw new IllegalStateException(e);}}public Principal require(String authorization,String...roles){if(authorization==null||!authorization.startsWith("Bearer "))throw new SecurityException("Authentication required");try(var c=db.connection();var s=c.prepareStatement("SELECT u.id,u.role FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at>CURRENT_TIMESTAMP")){s.setString(1,digest(authorization.substring(7)));try(var r=s.executeQuery()){if(!r.next())throw new SecurityException("Invalid or expired token");var p=new Principal(r.getLong(1),r.getString(2));if(roles.length>0&&java.util.Arrays.stream(roles).noneMatch(p.role()::equals))throw new SecurityException("Forbidden");return p;}}catch(SQLException e){throw new IllegalStateException(e);}}public void logout(String authorization){if(authorization==null||!authorization.startsWith("Bearer "))return;try(var c=db.connection();var s=c.prepareStatement("DELETE FROM sessions WHERE token_hash=?")){s.setString(1,digest(authorization.substring(7)));s.executeUpdate();}catch(SQLException e){throw new IllegalStateException(e);}}private String digest(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}public record Session(String token,long userId,String role){}public record Principal(long userId,String role){}}
